package app.simple.felicity.engine.managers

import android.util.Log
import java.io.InputStream
import java.util.Locale
import java.util.regex.Pattern

/**
 * Parses headphone calibration curves generated by the AutoEQ project and
 * Equalizer APO parametric configuration files (.txt).
 *
 * Extracts:
 * - Pre-amplification gain (dB) to avoid digital clipping.
 * - Parametric filter bands with Center Frequency (Hz), Gain (dB), and Quality factor (Q).
 *
 * Formats supported:
 * ```
 * Preamp: -6.4 dB
 * Filter 1: ON PK Fc 28 Hz Gain 6.1 dB Q 1.34
 * Filter 2: ON LSC Fc 105 Hz Gain 5.5 dB Q 0.70
 * Filter 3: ON HSC Fc 10000 Hz Gain -2.0 dB Q 0.70
 * Filter 4: ON PK Fc 2400 Hz Gain -3.2 dB Q 2.50
 * ```
 *
 * Also tolerates files missing units, lowercase filter types, comments (`# ...`),
 * and varying whitespace.
 *
 * @author Hamza417
 */
object AutoEqParser {

    private const val TAG = "AutoEqParser"

    data class AutoEqProfile(
            val name: String,
            val preampDb: Float,
            val bands: List<Triple<Float, Float, Float>> // (gainDb, qFactor, centerFreqHz)
    )

    private val PREAMP_PATTERN = Pattern.compile(
            """(?i)^\s*Preamp\s*:\s*([+-]?[0-9]+(?:\.[0-9]+)?)\s*(?:dB)?"""
    )

    // Matches: Filter 1: ON PK Fc 28 Hz Gain 6.1 dB Q 1.34
    // or: Filter: PK Fc 1000 Gain -2.5 Q 1.41
    private val FILTER_PATTERN = Pattern.compile(
            """(?i)^\s*Filter(?:\s+\d+)?\s*:\s*(?:(ON|OFF)\s+)?([A-Z0-9]+)\s+.*?"""
    )

    private val FC_PATTERN = Pattern.compile("""(?i)Fc\s+([0-9]+(?:\.[0-9]+)?)\s*(?:Hz)?""")
    private val GAIN_PATTERN = Pattern.compile("""(?i)Gain\s+([+-]?[0-9]+(?:\.[0-9]+)?)\s*(?:dB)?""")
    private val Q_PATTERN = Pattern.compile("""(?i)Q\s+([0-9]+(?:\.[0-9]+)?)""")

    /**
     * Parses the text content of an AutoEQ or Equalizer APO parametric configuration file.
     *
     * @param content The raw text content of the profile.
     * @param defaultName Default profile name (e.g. from file name).
     * @return [AutoEqProfile] with parsed preamp and parametric bands, or null if no valid filters found.
     */
    fun parse(content: String, defaultName: String = "AutoEQ Profile"): AutoEqProfile? {
        var preampDb = 0f
        val bands = mutableListOf<Triple<Float, Float, Float>>()
        var detectedName: String? = null

        val lines = content.lines()
        for (line in lines) {
            val trimmed = line.trim()
            if (trimmed.isEmpty()) continue

            // Parse comments for title metadata if present
            if (trimmed.startsWith("#") || trimmed.startsWith("//")) {
                val commentContent = trimmed.trimStart('#', '/', ' ').trim()
                if (detectedName == null && commentContent.isNotEmpty() && !commentContent.startsWith("EqualizerAPO", ignoreCase = true)) {
                    detectedName = commentContent
                }
                continue
            }

            // Check for Preamp
            val preampMatcher = PREAMP_PATTERN.matcher(trimmed)
            if (preampMatcher.find()) {
                preampDb = preampMatcher.group(1)?.toFloatOrNull() ?: 0f
                continue
            }

            // Check for Filter line
            if (trimmed.startsWith("Filter", ignoreCase = true)) {
                // If filter is explicitly marked OFF, skip it
                if (trimmed.contains(" OFF ", ignoreCase = true)) {
                    continue
                }

                val fcMatcher = FC_PATTERN.matcher(trimmed)
                val gainMatcher = GAIN_PATTERN.matcher(trimmed)
                val qMatcher = Q_PATTERN.matcher(trimmed)

                val fc = if (fcMatcher.find()) fcMatcher.group(1)?.toFloatOrNull() else null
                val gain = if (gainMatcher.find()) gainMatcher.group(1)?.toFloatOrNull() else null
                val q = if (qMatcher.find()) qMatcher.group(1)?.toFloatOrNull() else 1.414f

                if (fc != null && gain != null && q != null) {
                    // Valid parametric filter: (gainDb, qFactor, centerFreqHz)
                    bands.add(Triple(gain, q, fc))
                }
            }
        }

        if (bands.isEmpty()) {
            Log.w(TAG, "No valid parametric EQ filters found in content.")
            return null
        }

        val finalName = detectedName?.takeIf { it.isNotBlank() } ?: defaultName
        Log.i(TAG, "Successfully parsed AutoEQ profile '$finalName' with ${bands.size} bands and Preamp: ${preampDb}dB")
        return AutoEqProfile(
                name = finalName,
                preampDb = preampDb,
                bands = bands
        )
    }

    /**
     * Parses an AutoEQ file from an [InputStream].
     */
    fun parse(inputStream: InputStream, defaultName: String = "AutoEQ Profile"): AutoEqProfile? {
        val content = inputStream.bufferedReader().use { it.readText() }
        return parse(content, defaultName)
    }
}

